SET LOCAL ROLE corpus_sem_publisher;
-- Stable relational consumers. Candidate releases supply rows, never SQL identifiers or bodies.
CREATE OR REPLACE FUNCTION sem.require_execution_operation(r text,operation text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $operation$
DECLARE supported jsonb; actual jsonb; expected jsonb; archived_abi text;
BEGIN
 IF NOT EXISTS(SELECT FROM sem.release WHERE release_id=r AND profile='semantic-2') THEN RETURN; END IF;
 SELECT convert_from(body,'UTF8')::jsonb->'inputs'->>'compiler_version' INTO archived_abi
 FROM sem.registry_row WHERE release_id=r AND kind='execution_model';
 IF archived_abi IS DISTINCT FROM data.execution_contract_descriptor()->>'execution_abi'
 AND operation NOT IN ('reload','open_read','query','explain','compile_projection',
  'capture_analytics','open_analysis','close_analysis','graph_project','graph_validate',
  'read_original','read_rendition','read_parsing_product') THEN
  RAISE EXCEPTION 'historical execution ABI is read-only: %',archived_abi USING ERRCODE='23514'; END IF;
 supported:=data.execution_contract_descriptor()->'supported_effects'->operation;
 IF supported IS NULL OR NOT EXISTS(SELECT FROM sem.execution_operation o WHERE o.release_id=r AND o.operation_id=operation
  AND o.implementation_id=supported->>'implementation' AND o.implementation_version=supported->>'version') THEN
  RAISE EXCEPTION 'unsupported execution operation % in release %',operation,r USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM sem.operation_effect e WHERE e.release_id=r AND e.operation_id=operation
  AND e.effect_version IS DISTINCT FROM data.execution_contract_descriptor()->'supported_effect_versions'->>e.effect_id)
 OR EXISTS(SELECT FROM sem.transition_effect e JOIN sem.execution_transition t USING(release_id,transition_id)
  WHERE e.release_id=r AND t.operation_id=operation
  AND e.effect_version IS DISTINCT FROM data.execution_contract_descriptor()->'supported_effect_versions'->>e.effect_id) THEN
  RAISE EXCEPTION 'unsupported execution effect version for %',operation USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_agg(effect_id ORDER BY effect_id),'[]'::jsonb) INTO actual
 FROM sem.operation_effect WHERE release_id=r AND operation_id=operation;
 IF actual IS DISTINCT FROM supported->'effects' THEN
  RAISE EXCEPTION 'unsupported execution effects for %',operation USING ERRCODE='23514'; END IF;
 SELECT COALESCE(jsonb_object_agg(t.transition_id,COALESCE((SELECT jsonb_agg(e.effect_id ORDER BY e.effect_id)
  FROM sem.transition_effect e WHERE e.release_id=r AND e.transition_id=t.transition_id),'[]'::jsonb)),'{}'::jsonb) INTO actual
 FROM sem.execution_transition t WHERE t.release_id=r AND t.operation_id=operation;
 IF actual IS DISTINCT FROM supported->'transitions' THEN
  RAISE EXCEPTION 'unsupported transition effects for %',operation USING ERRCODE='23514'; END IF;
END $operation$;
REVOKE ALL ON FUNCTION sem.require_execution_operation(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION sem.require_execution_operation(text,text) TO corpus_sem_writer,corpus_sem_reader,corpus_sem_admitter,corpus_sem_evaluator;


-- The registry qualifies every layer, including byte-frozen legacy source manifests.
CREATE OR REPLACE FUNCTION ops.register_parsing_source(p_task bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $register$
DECLARE source ops.parsing_product; value jsonb;
BEGIN
 SELECT * INTO STRICT source FROM ops.parsing_product WHERE task_id=p_task;
 IF EXISTS(SELECT FROM ops.parsing_layer_product WHERE task_id=p_task AND product_key='source') THEN
  IF NOT EXISTS(SELECT FROM ops.parsing_layer_product WHERE task_id=p_task AND product_key='source' AND content_digest=source.product_digest AND payload=source.payload) THEN RAISE EXCEPTION 'source registry identity differs' USING ERRCODE='23514'; END IF;
  RETURN;
 END IF;
 value:=convert_from(source.payload,'UTF8')::jsonb;
 INSERT INTO ops.parsing_layer_product(task_id,product_key,content_digest,release_id,kind,root_task_id,root_product_key,root_content_digest,contract_digest,operation,adapter_id,lifecycle,semantic_state,coverage,payload)
 VALUES(p_task,'source',source.product_digest,source.release_id,'source',p_task,'source',source.product_digest,source.contract_digest,'project_canonical',COALESCE(value->>'adapter_id','legacy-source'),source.lifecycle,source.semantic_state,source.provenance_state,source.payload);
 INSERT INTO kb.parsing_layer_representation(task_id,representation_id,kind,unit,extent_length,text_content,partition_state,recognition_state,encoding,decoder,newline_policy,text_content_utf8_base64,product_key) SELECT item.task_id,item.representation_id,item.kind,item.unit,item.extent_length,item.text_content,item.partition_state,item.recognition_state,item.encoding,item.decoder,item.newline_policy,item.text_content_utf8_base64,'source' FROM kb.parsing_representation item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_component(task_id,component_id,ordinal,category,representation_id,unit,start_offset,end_offset,product_key) SELECT item.task_id,item.component_id,item.ordinal,item.category,item.representation_id,item.unit,item.start_offset,item.end_offset,'source' FROM kb.parsing_component item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_node(task_id,node_id,kind,representation_id,unit,start_offset,end_offset,origin,origin_reason,name,value,ordinal,attribute_outcome,name_start_offset,name_end_offset,value_start_offset,value_end_offset,product_key) SELECT item.task_id,item.node_id,item.kind,item.representation_id,item.unit,item.start_offset,item.end_offset,item.origin,item.origin_reason,item.name,item.value,item.ordinal,item.attribute_outcome,item.name_start_offset,item.name_end_offset,item.value_start_offset,item.value_end_offset,'source' FROM kb.parsing_node item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_relationship(task_id,relationship_id,kind,ordinal,product_key) SELECT item.task_id,item.relationship_id,item.kind,item.ordinal,'source' FROM kb.parsing_relationship item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_endpoint(task_id,relationship_id,ordinal,role,target_task_id,component_id,node_id,dependency_name,product_key,target_product_key,target_content_digest) SELECT item.task_id,item.relationship_id,item.ordinal,item.role,item.target_task_id,item.component_id,item.node_id,item.dependency_name,'source','source',(SELECT product_digest FROM ops.parsing_product target WHERE target.task_id=item.target_task_id) FROM kb.parsing_endpoint item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_mapping(task_id,mapping_id,operation,reason,fidelity,product_key) SELECT item.task_id,item.mapping_id,item.operation,item.reason,item.fidelity,'source' FROM kb.parsing_mapping item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_mapping_endpoint(task_id,mapping_id,side,ordinal,target_task_id,dependency_name,representation_id,unit,start_offset,end_offset,product_key,target_product_key,target_content_digest) SELECT item.task_id,item.mapping_id,item.side,item.ordinal,item.target_task_id,item.dependency_name,item.representation_id,item.unit,item.start_offset,item.end_offset,'source','source',(SELECT product_digest FROM ops.parsing_product target WHERE target.task_id=item.target_task_id) FROM kb.parsing_mapping_endpoint item WHERE item.task_id=p_task;
INSERT INTO kb.parsing_layer_dependency(task_id,product_key,name,kind,target_task_id,target_product_key,target_content_digest,artifact_digest) SELECT item.task_id,'source',item.name,'product',item.target_task_id,'source',(SELECT product_digest FROM ops.parsing_product target WHERE target.task_id=item.target_task_id),NULL FROM kb.parsing_dependency item WHERE item.task_id=p_task;
END $register$;
REVOKE ALL ON FUNCTION ops.register_parsing_source(bigint) FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.publish_layered_parsing_product(p_task bigint,p_attempt bigint,p_holder text,p_contract text,p_payload bytea,p_artifacts bytea[] DEFAULT ARRAY[]::bytea[]) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $layer$
DECLARE job ops.task; run ops.run; root ops.parsing_layer_product; previous ops.parsing_layer_product;
 product jsonb; parsing_item jsonb; adapter jsonb; digest text; layer_key text; operation text;
BEGIN
 -- Completion and direct publication share the same run-before-task lock order.
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt<>p_attempt OR job.claimed_by IS DISTINCT FROM p_holder THEN RAISE EXCEPTION 'stale layered product attempt' USING ERRCODE='P0004'; END IF;
 product:=convert_from(p_payload,'UTF8')::jsonb; digest:=encode(sha256(p_payload),'hex');
 IF jsonb_typeof(product) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: LayeredParsingProduct' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(product) key WHERE key<>ALL(ARRAY['product_key','kind','root','operation','adapter_id','lifecycle','semantic_state','coverage','representations','components','nodes','relationships','endpoints','mappings','mapping_endpoints','dependencies','interpretations','assessments'])) OR NOT (product ? 'product_key') OR (product ? 'product_key' AND (jsonb_typeof(product->'product_key') IS DISTINCT FROM 'string')) OR NOT (product ? 'kind') OR (product ? 'kind' AND (jsonb_typeof(product->'kind') IS DISTINCT FROM 'string' OR product->>'kind' NOT IN ('assessment','interpretation','source','text'))) OR NOT (product ? 'root') OR (product ? 'root' AND (jsonb_typeof(product->'root') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(product->'root') key WHERE key<>ALL(ARRAY['task_id','product_key','content_digest'])) OR NOT (product->'root' ? 'task_id') OR (product->'root' ? 'task_id' AND (jsonb_typeof(product->'root'->'task_id') IS DISTINCT FROM 'number' OR product->'root'->>'task_id' !~ '^[0-9]+$')) OR (product->'root' ? 'task_id' AND (product->'root'->>'task_id')::numeric < 1) OR NOT (product->'root' ? 'product_key') OR (product->'root' ? 'product_key' AND (jsonb_typeof(product->'root'->'product_key') IS DISTINCT FROM 'string')) OR NOT (product->'root' ? 'content_digest') OR (product->'root' ? 'content_digest' AND (jsonb_typeof(product->'root'->'content_digest') IS DISTINCT FROM 'string'))))) OR NOT (product ? 'operation') OR (product ? 'operation' AND (jsonb_typeof(product->'operation') IS DISTINCT FROM 'string')) OR NOT (product ? 'adapter_id') OR (product ? 'adapter_id' AND (jsonb_typeof(product->'adapter_id') IS DISTINCT FROM 'string')) OR NOT (product ? 'lifecycle') OR (product ? 'lifecycle' AND (jsonb_typeof(product->'lifecycle') IS DISTINCT FROM 'string' OR product->>'lifecycle' NOT IN ('available','cancelled','failed','not_requested','pending','running'))) OR NOT (product ? 'semantic_state') OR (product ? 'semantic_state' AND (jsonb_typeof(product->'semantic_state') IS DISTINCT FROM 'string' OR product->>'semantic_state' NOT IN ('ambiguous','invalid','ok','unknown','unsupported'))) OR NOT (product ? 'coverage') OR (product ? 'coverage' AND (jsonb_typeof(product->'coverage') IS DISTINCT FROM 'string' OR product->>'coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR (product ? 'representations' AND (jsonb_typeof(product->'representations') IS DISTINCT FROM 'array')) OR (product ? 'components' AND (jsonb_typeof(product->'components') IS DISTINCT FROM 'array')) OR (product ? 'nodes' AND (jsonb_typeof(product->'nodes') IS DISTINCT FROM 'array')) OR (product ? 'relationships' AND (jsonb_typeof(product->'relationships') IS DISTINCT FROM 'array')) OR (product ? 'endpoints' AND (jsonb_typeof(product->'endpoints') IS DISTINCT FROM 'array')) OR (product ? 'mappings' AND (jsonb_typeof(product->'mappings') IS DISTINCT FROM 'array')) OR (product ? 'mapping_endpoints' AND (jsonb_typeof(product->'mapping_endpoints') IS DISTINCT FROM 'array')) OR (product ? 'dependencies' AND (jsonb_typeof(product->'dependencies') IS DISTINCT FROM 'array')) OR (product ? 'interpretations' AND (jsonb_typeof(product->'interpretations') IS DISTINCT FROM 'array')) OR (product ? 'assessments' AND (jsonb_typeof(product->'assessments') IS DISTINCT FROM 'array')) THEN RAISE EXCEPTION 'parsing record shape differs: LayeredParsingProduct' USING ERRCODE='23514'; END IF;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'representations','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingRepresentation' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['text_content_utf8_base64','representation_id','kind','unit','extent_length','text_content','partition_state','recognition_state','encoding','decoder','newline_policy'])) OR (parsing_item ? 'text_content_utf8_base64' AND (jsonb_typeof(parsing_item->'text_content_utf8_base64') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'representation_id') OR (parsing_item ? 'representation_id' AND (jsonb_typeof(parsing_item->'representation_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'kind') OR (parsing_item ? 'kind' AND (jsonb_typeof(parsing_item->'kind') IS DISTINCT FROM 'string' OR parsing_item->>'kind' NOT IN ('artifact','canonical','decoded','expanded','original','parse_view'))) OR NOT (parsing_item ? 'unit') OR (parsing_item ? 'unit' AND (jsonb_typeof(parsing_item->'unit') IS DISTINCT FROM 'string' OR parsing_item->>'unit' NOT IN ('byte','codepoint'))) OR NOT (parsing_item ? 'extent_length') OR (parsing_item ? 'extent_length' AND (jsonb_typeof(parsing_item->'extent_length') IS DISTINCT FROM 'number' OR parsing_item->>'extent_length' !~ '^[0-9]+$')) OR (parsing_item ? 'extent_length' AND (parsing_item->>'extent_length')::numeric < 0) OR (parsing_item ? 'text_content' AND (jsonb_typeof(parsing_item->'text_content') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'partition_state') OR (parsing_item ? 'partition_state' AND (jsonb_typeof(parsing_item->'partition_state') IS DISTINCT FROM 'string' OR parsing_item->>'partition_state' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (parsing_item ? 'recognition_state') OR (parsing_item ? 'recognition_state' AND (jsonb_typeof(parsing_item->'recognition_state') IS DISTINCT FROM 'string' OR parsing_item->>'recognition_state' NOT IN ('complete','partial','unknown','unsupported'))) OR (parsing_item ? 'encoding' AND (jsonb_typeof(parsing_item->'encoding') IS DISTINCT FROM 'string')) OR (parsing_item ? 'decoder' AND (jsonb_typeof(parsing_item->'decoder') IS DISTINCT FROM 'string')) OR (parsing_item ? 'newline_policy' AND (jsonb_typeof(parsing_item->'newline_policy') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingRepresentation' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'components','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingComponent' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['component_id','ordinal','category','representation_id','unit','start_offset','end_offset'])) OR NOT (parsing_item ? 'component_id') OR (parsing_item ? 'component_id' AND (jsonb_typeof(parsing_item->'component_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'ordinal') OR (parsing_item ? 'ordinal' AND (jsonb_typeof(parsing_item->'ordinal') IS DISTINCT FROM 'number' OR parsing_item->>'ordinal' !~ '^[0-9]+$')) OR (parsing_item ? 'ordinal' AND (parsing_item->>'ordinal')::numeric < 0) OR NOT (parsing_item ? 'category') OR (parsing_item ? 'category' AND (jsonb_typeof(parsing_item->'category') IS DISTINCT FROM 'string' OR parsing_item->>'category' NOT IN ('attribute_delimiter','attribute_name','attribute_value','canonical_separator','character','character_reference','comment','control_symbol','control_word','doctype','encoding_marker','group_close','group_open','malformed','marker','markup','math','parameter','raw_text','reference','tag_close','tag_name','tag_open','text','unknown','whitespace'))) OR NOT (parsing_item ? 'representation_id') OR (parsing_item ? 'representation_id' AND (jsonb_typeof(parsing_item->'representation_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'unit') OR (parsing_item ? 'unit' AND (jsonb_typeof(parsing_item->'unit') IS DISTINCT FROM 'string' OR parsing_item->>'unit' NOT IN ('byte','codepoint'))) OR NOT (parsing_item ? 'start_offset') OR (parsing_item ? 'start_offset' AND (jsonb_typeof(parsing_item->'start_offset') IS DISTINCT FROM 'number' OR parsing_item->>'start_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'start_offset' AND (parsing_item->>'start_offset')::numeric < 0) OR NOT (parsing_item ? 'end_offset') OR (parsing_item ? 'end_offset' AND (jsonb_typeof(parsing_item->'end_offset') IS DISTINCT FROM 'number' OR parsing_item->>'end_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'end_offset' AND (parsing_item->>'end_offset')::numeric < 0) THEN RAISE EXCEPTION 'parsing record shape differs: ParsingComponent' USING ERRCODE='23514'; END IF;
END LOOP;
FOR parsing_item IN SELECT value FROM jsonb_array_elements(COALESCE(product->'nodes','[]'::jsonb)) LOOP
IF jsonb_typeof(parsing_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: ParsingNode' USING ERRCODE='23514'; END IF;
IF ((EXISTS(SELECT FROM jsonb_object_keys(parsing_item) key WHERE key<>ALL(ARRAY['kind','origin','representation_id','unit','start_offset','end_offset','name','value','ordinal','attribute_outcome','name_start_offset','name_end_offset','value_start_offset','value_end_offset','node_id','origin_reason'])) OR NOT (parsing_item ? 'kind') OR (parsing_item ? 'kind' AND (jsonb_typeof(parsing_item->'kind') IS DISTINCT FROM 'string')) OR parsing_item->>'kind' IS DISTINCT FROM 'attribute' OR NOT (parsing_item ? 'origin') OR (parsing_item ? 'origin' AND (jsonb_typeof(parsing_item->'origin') IS DISTINCT FROM 'string')) OR parsing_item->>'origin' IS DISTINCT FROM 'literal' OR NOT (parsing_item ? 'representation_id') OR (parsing_item ? 'representation_id' AND (jsonb_typeof(parsing_item->'representation_id') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'unit') OR (parsing_item ? 'unit' AND (jsonb_typeof(parsing_item->'unit') IS DISTINCT FROM 'string' OR parsing_item->>'unit' NOT IN ('byte','codepoint'))) OR NOT (parsing_item ? 'start_offset') OR (parsing_item ? 'start_offset' AND (jsonb_typeof(parsing_item->'start_offset') IS DISTINCT FROM 'number' OR parsing_item->>'start_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'start_offset' AND (parsing_item->>'start_offset')::numeric < 0) OR NOT (parsing_item ? 'end_offset') OR (parsing_item ? 'end_offset' AND (jsonb_typeof(parsing_item->'end_offset') IS DISTINCT FROM 'number' OR parsing_item->>'end_offset' !~ '^[0-9]+$')) OR (parsing_item ? 'end_offset' AND (parsing_item->>'end_offset')::numeric < 0) OR NOT (parsing_item ? 'name') OR (parsing_item ? 'name' AND (jsonb_typeof(parsing_item->'name') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'value') OR (parsing_item ? 'value' AND (jsonb_typeof(parsing_item->'value') IS DISTINCT FROM 'string')) OR NOT (parsing_item ? 'ordinal') OR (parsing_item ? 'ordinal' AND (jsonb_typeof(parsing_item->'ordinal') IS DISTINCT FROM 'number' OR parsing_item->>'ordinal' !~ '^[0-9]+$')) OR (parsing_i